#import "../../../template.typ": *
#import "../support.typ": *

#let slide_05() = slide[
  #slide-head("05", [Suspension Requires Encoder-Owned State])

  #v(0.45em)

  #grid(
    columns: (auto, auto, 1fr),
    gutter: 6pt,
    align: horizon,
  )[
    #chip([a415231 Make async encode state encoder-owned], fill: green-soft, accent: green, size: 7pt)
  ][
    #chip([617cd50 Split encoder async state], fill: green-soft, accent: green, size: 7pt)
  ][
    #align(right)[#chip([correction after poll-codec experiments], fill: violet-soft, accent: violet, size: 7pt)]
  ]

  #v(0.5em)

  #thesis([Any state that can survive `Pending` must be owned by the encode operation.], fill: green-soft, accent: green, size: 10.4pt)

  #v(0.55em)

  #grid(columns: (1fr, auto, 1fr), gutter: 8pt, align: horizon)[
    #soft-card([Before], [
      #align(center)[#text(size: 10pt, weight: "bold", fill: orange)[driver owns too much temporary state]]
      #v(0.35em)
      #grid(columns: (1fr,), gutter: 4pt)[
        #flow-step([body driver / stream task], fill: white, accent: gray, size: 7.6pt)
      ][
        #flow-step([temporary item + dst + progress], fill: orange-soft, accent: orange, size: 7.4pt)
      ][
        #flow-step([polls encoder while retaining pieces], fill: red-soft, accent: red, size: 7.2pt)
      ]
      #v(0.25em)
      #align(center)[#text(size: 7.3pt, fill: ink-soft)[`Pending` leaves ownership split across layers.]]
    ], fill: orange-soft, accent: orange, body-size: 8pt)
  ][
    #align(center)[
      #text(size: 7.4pt, fill: palette.muted)[move the suspendable lifetime]
      #v(0.2em)
      #arrow
    ]
  ][
    #soft-card([After], [
      #align(center)[#text(size: 10pt, weight: "bold", fill: blue)[encoder future owns resumable encode state]]
      #v(0.35em)
      #grid(columns: (1fr,), gutter: 4pt)[
        #flow-step([start one owned future], fill: white, accent: blue, size: 7.6pt)
      ][
        #flow-step([future holds message + buffer + resume cursor], fill: blue-soft, accent: blue, size: 7.1pt)
      ][
        #flow-step([driver polls only the future], fill: green-soft, accent: green, size: 7.4pt)
      ]
      #v(0.25em)
      #align(center)[#text(size: 7.3pt, fill: ink-soft)[`Ready` returns the completed destination buffer.]]
    ], fill: blue-soft, accent: blue, body-size: 8pt)
  ]

  #v(0.55em)

  #soft-card([State inventory owned by the encode operation], [
    #grid(
      columns: (1fr, 1fr, 1fr),
      gutter: 5pt,
    )[
      #chip([message / item], fill: blue-soft, accent: blue)
    ][
      #chip([destination buffer], fill: blue-soft, accent: blue)
    ][
      #chip([protobuf field position], fill: violet-soft, accent: violet)
    ][
      #chip([pending payload copy], fill: orange-soft, accent: orange)
    ][
      #chip([DSA descriptor / completion], fill: red-soft, accent: red)
    ][
      #chip([retry / drop state], fill: green-soft, accent: green)
    ]
  ], fill: panel-fill, accent: blue, body-size: 7.8pt)

  #v(0.45em)

  #warning-band[
    Polling can be split across calls; ownership cannot be split across layers that outlive the same `Pending`.
  ]

  #v(1fr)
  #speaker[Once encoding can suspend, “where does the state live?” becomes the API design question.]
]

